def digest(data):return hashlib.sha256(data).hexdigest()
def outside(im,box):
 q=im.copy();ImageDraw.Draw(q).rectangle((box[0],box[1],box[2]-1,box[3]-1),fill='black');return digest(q.tobytes())
def main():
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--check',action='store_true');args=ap.parse_args()
 planned=[]
 for s in SPECS:
  p=ROOT/s['file'];im=Image.open(p).convert('RGB');box=tuple(s['box']);font=ImageFont.truetype(str(ROOT/'assets/fonts/NotoSansSC-Regular.ttf'),s['font_size'])
  expected=[]
  for title in (s['old'],s['title']):
   test=Image.new('RGB',im.size,s['bg']);ImageDraw.Draw(test).text(tuple(s['xy']),title,font=font,fill=s['ink']);expected.append(test.crop(box).tobytes())
  actual=im.crop(box).tobytes();current=actual==expected[1]
  if not current:
   if actual!=expected[0] or digest(p.read_bytes())!=s['baseline_sha256']:raise RuntimeError('Unexpected source; refusing title edit: '+s['file'])
   if args.check:raise RuntimeError('Title requires migration: '+s['file'])
  out=im.copy();ImageDraw.Draw(out).rectangle((box[0],box[1],box[2]-1,box[3]-1),fill=s['bg']);ImageDraw.Draw(out).text(tuple(s['xy']),s['title'],font=font,fill=s['ink'])
  before=outside(im,box);after=outside(out,box)
  if before!=after:raise RuntimeError('Pixels outside title changed: '+s['file'])
  planned.append((s,p,out,current,before))
 records=[]
 for s,p,out,current,h in planned:
  if not current:
   tmp=p.with_name('.'+p.name+'.title-update.tmp');out.save(tmp,format='PNG',optimize=True);tmp.replace(p)
  records.append({'file':s['file'],'title_rectangle':s['box'],'old_title':s['old'],'current_title':s['title'],'baseline_sha256':s['baseline_sha256'],'current_sha256':digest(p.read_bytes()),'outside_before_sha256':h,'outside_after_sha256':outside(out,tuple(s['box'])),'outside_pixels_unchanged':True})
 report={'count':len(records),'updated':sum(not p[3] for p in planned),'already_current':sum(p[3] for p in planned),'check_only':args.check,'all_outside_pixels_identical':True,'records':records}
 if not args.check:(ROOT/'references/diagram-title-update-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({k:v for k,v in report.items() if k!='records'},ensure_ascii=False))
if __name__=='__main__':main()
